/* Account hub, part 3: notifications, profile, access tokens and approving a device, and the glue to the shell. */
const accTabs = (cur) => `<div class="subtabs" role="tablist" aria-label="Your account">${[['profile', 'Profile'], ['tokens', 'Access tokens']].map(([k, n]) => `<button type="button" class="subtab" role="tab" aria-selected="${k === cur}" data-go="${k}">${n}</button>`).join('')}</div>`;

function pNotifications() {
  const all = S.notifications; const list = all.filter((n) => H.notifFilter === 'All' || n.unread); const unread = all.filter((n) => n.unread).length;
  const rows = list.length ? list.map((n) => `<div class="notif" ${n.unread ? 'data-unread' : ''}><span aria-hidden="true" style="width:14px;flex:none;margin-top:6px">${n.unread ? '<span class="dot"></span>' : ''}</span><div class="tx">${n.unread ? '<span class="visually-hidden">Unread. </span>' : ''}<a href="#/${n.go}" data-read="${n.id}" style="color:var(--text-primary);text-decoration:none"><b>${esc(n.text)}</b></a><div class="t-meta">${esc(n.when)}</div></div>${n.unread ? `<button type="button" class="btn btn--quiet" data-act="mark-read" data-id="${n.id}">Mark read</button>` : ''}</div>`).join('') : `<div class="empty-inline">${slot('caught-up', 'Catileo, curled sleep')}<div class="t-sub" style="margin-top:var(--s-2h)">You’re all caught up.</div></div>`;
  return `<div class="page page-enter" style="max-width:760px"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Notifications</h1><p class="page-sub" style="margin-bottom:0">${unread ? unread + ' unread' : 'Nothing unread'}</p></div><div class="row2"><div class="seg" role="radiogroup" aria-label="Show">${['All', 'Unread'].map((f) => `<button type="button" role="radio" aria-checked="${H.notifFilter === f}" data-act="notif-filter" data-v="${f}">${f}</button>`).join('')}</div><button type="button" class="btn" data-act="mark-all" ${unread ? '' : 'aria-disabled="true"'}>Mark all as read</button></div></div><div class="listcard" style="margin-top:var(--s-3)">${rows}</div></div>`;
}
Object.assign(window.HUB_ACTS2, {
  'notif-filter': (a) => { H.notifFilter = a.dataset.v; refresh(); },
  'mark-read': (a) => { const n = S.notifications.find((x) => x.id === a.dataset.id); n.unread = false; renderHeader(); refresh(); },
  'mark-all': (a) => { if (a.getAttribute('aria-disabled') === 'true') return; markAllRead(); refresh(); }
});

const COLORS = [['Blue', 'var(--brand-archive-blue)'], ['Sky', 'var(--brand-astral-blue)'], ['Green', 'var(--utility-success)'], ['Burgundy', 'var(--brand-burgundy)'], ['Grey', 'var(--text-secondary)']];
function pProfile() {
  return `<div class="page page-enter form"><p class="crumb">Account</p><h1 class="t-title page-title">Your account</h1>${accTabs('profile')}<div data-form>
  <section class="form-sec"><div><h2 class="t-heading">Picture</h2><p class="muted" style="margin-top:4px">Shown next to your name in lists.</p></div><div class="row2"><span class="avatar-lg" style="display:inline-flex;align-items:center;justify-content:center;width:72px;height:72px;border-radius:14px;background:var(--surface-selected);font-family:var(--font-display);font-size:1.6rem">DO</span><button type="button" class="btn" data-act="toast" data-title="A picture is chosen in a picker">Replace</button><button type="button" class="btn btn--quiet" data-act="toast" data-title="Picture removed">Remove</button></div></section>
  <section class="form-sec"><div><h2 class="t-heading">Names</h2><p class="muted" style="margin-top:4px">What people call you, and how.</p></div><div class="fields"><div><label class="label" for="pf-n">Nickname</label><input id="pf-n" class="input" data-f value="dana"><div class="help">Others find you by it.</div></div><div><label class="label" for="pf-d">Display name</label><input id="pf-d" class="input" data-f value="Dana Okafor"></div><div><label class="label" for="pf-p">Pronouns</label><input id="pf-p" class="input" data-f value="she/her"></div></div></section>
  <section class="form-sec"><div><h2 class="t-heading">About you</h2></div><div class="fields"><div><label class="label" for="pf-b">Bio</label><textarea id="pf-b" class="input" rows="3" data-f style="padding:8px 12px">I run the Thursday game and keep too many notes.</textarea></div><div><label class="label" for="pf-l">Languages</label><input id="pf-l" class="input" data-f value="English, Deutsch"></div><div><span class="label">Your colour</span><div class="row2" role="group" aria-label="Your colour">${COLORS.map(([n, c], i) => `<button type="button" class="swatch" aria-pressed="${i === 0}" data-act="swatch"><i style="background:${c}"></i>${n}</button>`).join('')}</div><div class="help">It marks you next to your name. The name is what identifies you.</div></div></div></section>
  <section class="form-sec"><div><h2 class="t-heading">Delete my account</h2><p class="muted" style="margin-top:4px">This removes your profile and what you own. It does not delete your login.</p></div><div><button type="button" class="btn btn--danger" data-act="delete-acct">Delete my account…</button></div></section></div></div>`;
}
const TOK = { list: HUB.tokens.map((t) => ({ ...t })), code: '', device: null };
function pTokens() {
  const rows = TOK.list.map((t) => `<div class="tr" style="grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) 130px"><span class="nm">${esc(t.name)}<span class="t-meta" style="display:block">Ends in <code>${esc(t.hint)}</code></span></span><span><span class="lbl">Made</span>${esc(t.made)}</span><span><span class="lbl">Last used</span>${esc(t.used)}</span><span><span class="lbl">Expires</span>${esc(t.ends)}</span><span><button type="button" class="btn btn--quiet" data-act="revoke-token" data-id="${t.id}">Revoke…</button></span></div>`).join('') || '<div class="tr"><span class="muted">No access tokens. A device asks for one when you connect it.</span></div>';
  const dev = TOK.device ? `<div class="card col-gap" style="margin-top:var(--s-2h)"><div class="row2">${ic('device', 'lg')}<div><b>${esc(TOK.device)}</b> is asking to act as you.</div></div><div><label class="label" for="dv-n">Name for this token</label><input id="dv-n" class="input" value="${esc(TOK.device)}"></div><div><span class="label">Expires</span><div class="seg" role="radiogroup" aria-label="Expires" id="dv-e">${['Never', '1 month', '3 months', '1 year'].map((t, i) => `<button type="button" role="radio" aria-checked="${i === 2}" data-v="${t}">${t}</button>`).join('')}</div></div>${hubCallout('warning', '<b>It can do what you can,</b> except manage tokens or delete your account. You can revoke it at any time.', 'warn')}<div class="row2"><button type="button" class="btn btn--primary" data-act="approve">Approve</button><button type="button" class="btn" data-act="deny">Deny</button></div></div>` : '';
  return `<div class="page page-enter" style="max-width:880px"><p class="crumb">Account</p><h1 class="t-title page-title">Your account</h1>${accTabs('tokens')}<section aria-labelledby="tk-h"><div class="sec-h"><h2 id="tk-h">Access tokens</h2></div><p class="muted" style="margin-bottom:var(--s-2h)">A token lets a device such as the command line act as you. A token is shown to the device when you approve it, and never again.</p><div class="tbl2"><div class="th" style="grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) 130px"><span>Name</span><span>Made</span><span>Last used</span><span>Expires</span><span></span></div>${rows}</div></section>
  <section aria-labelledby="dv-h" style="margin-top:var(--s-5)"><div class="sec-h"><h2 id="dv-h">Connect a device</h2></div><p class="muted" style="margin-bottom:var(--s-2h)">Run the login on the device. It shows a code. Enter it here.</p><div class="row2"><label class="visually-hidden" for="dv-c">Code from the device</label><input id="dv-c" class="input t-code" style="width:200px" placeholder="ABCD-EFGH" value="${esc(TOK.code)}" maxlength="9" autocomplete="off"><button type="button" class="btn" data-act="find-device">Check the code</button></div><div id="dv-err" class="help" role="alert"></div>${dev}</section></div>`;
}
Object.assign(window.HUB_ACTS2, {
  swatch: (a) => { $$('.swatch').forEach((s) => s.setAttribute('aria-pressed', s === a)); },
  'delete-acct': () => confirmByName(DATA.user.email, 'Delete my account?', 'This removes your profile and the libraries and repositories only you own. It cannot be undone. Your login is not deleted.', () => toast({ title: 'Nothing was deleted', text: 'The prototype never deletes anything.' })),
  'revoke-token': (a) => { const t = TOK.list.find((x) => x.id === a.dataset.id); confirmSimple(`Revoke ${t.name}?`, 'The device stops working at once. It cannot be undone; connect it again to get a new token.', 'Revoke', () => { TOK.list = TOK.list.filter((x) => x !== t); refresh(); toast({ title: `${t.name} revoked` }); }); },
  'find-device': () => { const v = $('#dv-c').value.trim(); TOK.code = v; if (!/^[A-Za-z]{4}-?[A-Za-z]{4}$/.test(v)) { $('#dv-err').textContent = 'That code is not valid or has ended. Start again on the device.'; $('#dv-err').style.color = 'var(--danger)'; TOK.device = null; return; } TOK.device = 'lorenzo-cli on Dana’s laptop'; refresh(); },
  approve: () => { const e = ($('#dv-e [aria-checked="true"]') || {}).dataset || {}; TOK.list.unshift({ id: 't' + Date.now(), name: $('#dv-n').value || 'A device', hint: 'n4Rw', made: 'Today', used: 'Never', ends: e.v || '3 months' }); TOK.device = null; TOK.code = ''; refresh(); toast({ title: 'Approved', text: 'The device is connected. Its token is shown to the device only.' }); },
  deny: () => { TOK.device = null; refresh(); toast({ title: 'Denied' }); }
});
document.addEventListener('click', (e) => { const b = e.target.closest('#dv-e button'); if (b) $$('#dv-e button').forEach((x) => x.setAttribute('aria-checked', x === b)); const r = e.target.closest('[data-read]'); if (r) { const n = S.notifications.find((x) => x.id === r.dataset.read); if (n) { n.unread = false; renderHeader(); } } });

/* ---------------------------------------------------------------- glue to the shell */
window.START_ROUTE = 'hub';
window.TAB_HIDE = (t) => t === 'discover' && !S.publicRepos;
window.GO_EXT = { h: 'hub', a: 'hub' };
const metaOf = (f) => () => f();
window.ROUTES_EXT = {
  hub: { app: 'account', tab: 'hub', render: pHubHome, after: () => { if (H.acct === 'new') { afterFirstRun(); } else hubAfter(); }, meta: () => (H.acct === 'new' ? 'No library yet' : `${needs().length} need you`) },
  libraries: { app: 'account', tab: 'libraries', render: pLibraries, after: hubAfter, meta: () => `${myLibs().length} libraries` },
  library: { app: 'account', tab: 'libraries', render: pLibrary, after: hubAfter, meta: () => { const l = hl(parts()[1]); return l ? `${pl(l.people.length || 1, 'person', 'people')} · ${pl(l.campaigns.length, 'campaign', 'campaigns')}` : ''; } },
  repositories: { app: 'account', tab: 'repositories', render: pRepositories, after: afterRepositories, meta: () => `${HUB.repos.length} repositories` },
  repo: { app: 'account', tab: 'repositories', render: pRepo, after: hubAfter, meta: () => { const r = hr(parts()[1]); return r ? `${r.counts.entries} entries` : ''; } },
  discover: { app: 'account', tab: 'discover', render: pDiscover, after: afterDiscover, meta: () => `${HUB.discover.length} public repositories` },
  notifications: { app: 'account', tab: 'hub', render: pNotifications, after: hubAfter, meta: () => `${S.notifications.filter((n) => n.unread).length} unread` },
  profile: { app: 'account', tab: 'hub', render: pProfile, after: hubAfter, meta: () => 'Your account' },
  tokens: { app: 'account', tab: 'hub', render: pTokens, after: hubAfter, meta: () => `${TOK.list.length} tokens` },
  device: { app: 'account', tab: 'hub', render: () => { TOK.code = 'KHWT-QPLM'; TOK.device = 'lorenzo-cli on Dana’s laptop'; return pTokens(); }, after: hubAfter, meta: () => 'Connect a device' }
};
/* The controls bar: the unsettled layouts and the roles, to compare by clicking */
const PB = (k, v, t, on) => `<button type="button" data-p="${k}" data-v="${v}" aria-pressed="${on}">${t}</button>`;
window.PROTO_EXT = () => `<span class="group"><b>Account</b>${[['busy', 'Busy'], ['quiet', 'Quiet'], ['new', 'New']].map(([v, t]) => PB('acct', v, t, H.acct === v)).join('')}</span><span class="group"><b>Your role in a library or repository</b>${[['asis', 'As is'], ['Owner', 'Owner'], ['Organizer', 'Organizer'], ['Author', 'Author'], ['Player', 'No role']].map(([v, t]) => PB('hrole', v, t, H.role === v)).join('')}</span><span class="group"><b>May create</b>${[['1', 'Yes'], ['0', 'No']].map(([v, t]) => PB('hcreate', v, t, String(+H.create) === v)).join('')}</span>`;
window.PROTO_SYNC = () => { $$('#proto [data-p]').forEach((b) => { const k = b.dataset.p, v = b.dataset.v; if (k === 'acct') b.setAttribute('aria-pressed', H.acct === v); else if (k === 'hrole') b.setAttribute('aria-pressed', H.role === v); else if (k === 'hcreate') b.setAttribute('aria-pressed', String(+H.create) === v); }); };
window.PROTO_CLICK = (k, v) => {
  if (k === 'acct') { H.acct = v; go('hub'); return true; }
  if (k === 'hrole') { H.role = v; render(true); return true; }
  if (k === 'hcreate') { H.create = v === '1'; render(true); return true; }
  return false;
};
